def f(N: int, edges: List[Tuple[int, int]]):
    graph = {i+1: [] for i in range(N)}
    for a, b in edges:
        graph[a].append(b)
        graph[b].append(a)
    parent = {i: i for i in range(1, N+1)}
    def find(i):
        if parent[i]!= i:
            parent[i] = find(parent[i])
        return parent[i]
    def union(a, b):
        parent[find(a)] = find(b)
    for i in range(1, N+1):
        if len(graph[i]) < 2:
            if len(graph[i]) == 0:
                continue
            union(graph[i][0], i)
            return i
    return -1
